<?php $locked=false;foreach($purchaseLines as $line)if((float)$line['received_quantity']>0)$locked=true; ?>
<div class="col-12" data-purchase-editor>
<div class="d-flex justify-content-between"><h4 class="h6">Artigos da encomenda</h4><?php if(!$locked):?><button type="button" class="btn btn-sm btn-outline-primary" data-add-line><i class="bi bi-plus-lg"></i> Adicionar linha</button><?php endif;?></div>
<p class="small text-muted">Selecione o artigo para carregar o código, descrição, unidade e preço. A percentagem global é a média das percentagens recebidas por linha.</p>
<?php if($locked):?><p class="alert alert-info">Os artigos estão bloqueados porque já existem receções.</p><?php endif;?>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Artigo</th><th>Unidade</th><th>Quantidade</th><th>Preço unitário</th><th>Recebido</th><th></th></tr></thead><tbody data-order-lines></tbody></table></div>
<template data-line-template><tr><td style="min-width:320px"><select class="form-select js-searchable-select" data-search-placeholder="Pesquisar código ou descrição…" data-item required <?=$locked?'disabled':''?>><option value="">Selecione o artigo…</option><?php foreach(['raw_material'=>$rawMaterials,'finished_product'=>$finishedProducts] as $type=>$items):?><optgroup label="<?=$type==='raw_material'?'Matérias-primas':'Artigos acabados'?>"><?php foreach($items as $item):?><option value="<?=$type?>:<?=(int)$item['id']?>" data-unit="<?=h((string)($item['unit_code']??''))?>" data-price="<?=h((string)($item['last_price']??$item['standard_cost']??0))?>"><?=h($item['code'].' — '.$item['description'])?></option><?php endforeach;?></optgroup><?php endforeach;?></select><input type="hidden" name="line_item_type[]"><input type="hidden" name="line_item_id[]"></td><td data-line-unit></td><td><input class="form-control" type="number" min="0.001" step="0.001" name="line_quantity[]" required <?=$locked?'readonly':''?>></td><td><input class="form-control" type="number" min="0" step="0.001" name="line_unit_cost[]" required <?=$locked?'readonly':''?>></td><td data-received></td><td><?php if(!$locked):?><button type="button" class="btn btn-outline-danger" data-remove aria-label="Remover linha"><i class="bi bi-trash"></i></button><?php endif;?></td></tr></template>
</div>
<script>
(function(){var box=document.querySelector('[data-purchase-editor]'),body=box.querySelector('[data-order-lines]'),tpl=box.querySelector('template');function add(line){var row=tpl.content.firstElementChild.cloneNode(true),select=row.querySelector('[data-item]');function update(fill){var parts=select.value.split(':'),option=select.options[select.selectedIndex];row.querySelector('[name="line_item_type[]"]').value=parts[0]||'';row.querySelector('[name="line_item_id[]"]').value=parts[1]||'';row.querySelector('[data-line-unit]').textContent=option.dataset.unit||'';if(fill)row.querySelector('[name="line_unit_cost[]"]').value=option.dataset.price||0;}select.addEventListener('change',function(){update(true);});if(line){select.value=line.item_type+':'+line.item_id;row.querySelector('[name="line_quantity[]"]').value=line.quantity;row.querySelector('[name="line_unit_cost[]"]').value=line.unit_price;row.querySelector('[data-received]').textContent=line.received_quantity+' / '+line.quantity;update(false);}else{row.querySelector('[name="line_quantity[]"]').value=1;row.querySelector('[name="line_unit_cost[]"]').value=0;}var remove=row.querySelector('[data-remove]');if(remove)remove.onclick=function(){row.remove();};body.appendChild(row);if(window.GesTisserSearchableSelect)window.GesTisserSearchableSelect.init(row);}var lines=<?=json_encode($purchaseLines,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;lines.forEach(add);if(!lines.length)add();var button=box.querySelector('[data-add-line]');if(button)button.onclick=function(){add();};})();
</script>
